const dbRow   = $('Fetch Status Data').first().json;
const scans   = typeof dbRow.scans   === 'string' ? JSON.parse(dbRow.scans)   : (dbRow.scans   || []);
const signals = typeof dbRow.signals === 'string' ? JSON.parse(dbRow.signals) : (dbRow.signals || []);
const scansToday       = parseInt(dbRow.scans_today)       || 0;
const signalsToday     = parseInt(dbRow.signals_today)     || 0;
const interestingToday = parseInt(dbRow.interesting_today) || 0;
const totalScans       = parseInt(dbRow.total_scans)       || 0;
const autoActive       = $input.first().json.active;

const ts = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', hour12: false });

function fmt(v, digits) {
  if (v == null) return '<span class="dim">—</span>';
  const n = parseFloat(v);
  if (isNaN(n)) return '<span class="dim">—</span>';
  return n.toFixed(digits);
}
function pct(now, then) {
  if (now == null || then == null) return '<span class="dim">—</span>';
  const p = ((parseFloat(now) - parseFloat(then)) / parseFloat(then)) * 100;
  if (isNaN(p)) return '<span class="dim">—</span>';
  const s = (p >= 0 ? '+' : '') + p.toFixed(1) + '%';
  return `<span class="${p >= 0 ? 'pos' : 'neg'}">${s}</span>`;
}
function timeStr(iso) {
  return new Date(iso).toLocaleTimeString('en-US', {
    timeZone: 'America/New_York', hour12: false, hour:'2-digit', minute:'2-digit'
  });
}
function badge(cls, text) {
  return `<span class="badge badge-${cls}">${text}</span>`;
}

const scanRows = scans.map(s => {
  const src = s.trigger_type === 'auto' ? badge('auto','auto') : badge('manual','manual');
  const inter = s.interesting_count > 0 ? `<span class="interesting">${s.interesting_count}</span>` : `<span class="dim">0</span>`;
  const watch = s.watch_count > 0       ? `<span class="watch">${s.watch_count}</span>`             : `<span class="dim">0</span>`;
  const staleP = s.total_launches > 0 ? Math.round(s.stale_count / s.total_launches * 100) : 0;
  return `<tr>
    <td>${timeStr(s.scanned_at)}</td><td>${src}</td>
    <td>${s.total_launches ?? '—'}</td><td>${s.sent_to_llm ?? '—'}</td>
    <td>${s.stale_count ?? '—'} <span class="dim">(${staleP}%)</span></td>
    <td>${inter}</td><td>${watch}</td><td><span class="dim">${s.skip_count ?? '—'}</span></td>
  </tr>`;
}).join('');

const sigRows = signals.map(t => {
  const rat    = badge(t.rating.toLowerCase(), t.rating);
  const vlCls  = (parseFloat(t.vl_ratio) > 12 || parseFloat(t.vl_ratio) < 0.3) ? 'neg' : '';
  const out5   = t.price_at_5m  != null ? pct(t.price_at_5m,  t.price_usd) : '<span class="dim">…</span>';
  const out15  = t.price_at_15m != null ? pct(t.price_at_15m, t.price_usd) : '<span class="dim">…</span>';
  const out30  = t.price_at_30m != null ? pct(t.price_at_30m, t.price_usd) : '<span class="dim">…</span>';
  const micro  = {up:'<span class="pos">up</span>',down:'<span class="neg">down</span>',
                  fading:'<span class="neg">fading</span>',recovering:'<span class="pos">recovering</span>'}[t.micro_trend]
               || `<span class="dim">${t.micro_trend||'—'}</span>`;
  const volTr  = {rising:'<span class="pos">rising</span>',falling:'<span class="neg">falling</span>'}[t.vol_trend]
               || `<span class="dim">${t.vol_trend||'—'}</span>`;
  let tgtBadge = '', stpBadge = '';
  if (t.rating === 'INTERESTING') {
    tgtBadge = t.target_hit === true ? badge('hit','✓ target') : t.target_hit === false ? badge('miss','✗ target') : '<span class="dim">?</span>';
    stpBadge = t.stop_hit  === true ? badge('stopped','✗ stop') : t.stop_hit  === false ? badge('safe','✓ held')   : '<span class="dim">?</span>';
  }
  return `<tr>
    <td>${timeStr(t.scanned_at)}</td>
    <td><strong>${t.symbol||'—'}</strong></td>
    <td><span class="dim">${t.chain||''}</span></td>
    <td>${rat}</td><td>${t.age_minutes??'—'}m</td>
    <td>${fmt(t.price_usd,8)}</td>
    <td><span class="${vlCls}">${fmt(t.vl_ratio,1)}×</span></td>
    <td>${volTr}</td><td>${micro}</td><td>${fmt(t.buy_pct_5m,0)}%</td>
    <td>${out5}</td><td>${out15}</td><td>${out30}</td>
    <td>${tgtBadge}</td><td>${stpBadge}</td>
    <td style="max-width:260px;font-size:0.75em;color:#888;white-space:normal">${t.reasoning||''}</td>
  </tr>`;
}).join('');

