.pos{color:#00e676}.neg{color:#ef5350}
.section{font-size:0.7em;color:#555;text-transform:uppercase;letter-spacing:1px;margin:0 0 6px}
table{width:100%;border-collapse:collapse;margin-bottom:28px;font-size:0.78em}
th{background:#141414;color:#555;text-align:left;padding:5px 8px;border-bottom:1px solid #222;font-weight:500;white-space:nowrap}
td{padding:4px 8px;border-bottom:1px solid #181818;vertical-align:top;white-space:nowrap}
tr:hover td{background:#181818}
.badge{display:inline-block;padding:1px 5px;border-radius:3px;font-size:0.72em;font-weight:700;white-space:nowrap}
.badge-interesting{background:#00e67618;color:#00e676;border:1px solid #00e67644}
.badge-watch{background:#ffab4018;color:#ffab40;border:1px solid #ffab4044}
.badge-auto{background:#2196f318;color:#64b5f6;border:1px solid #2196f344}
